auth/auth.css:
/* ========================================
   PMP Management Center - Authentication
   ======================================== */
.auth-container {
    margin: 0;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    min-height: 100dvh;
    padding: 5px;
    background-color: var(--hisense-bg);
    color: #ccc;
    font-family: "Segoe UI", Arial, sans-serif;
}
.auth-container *,
.auth-container *::before,
.auth-container *::after {
    box-sizing: border-box;
}

.brand {
    gap: 15px;
    padding: 0px;
    margin-bottom: 40px;
}

.brand-mark {
    width: 60px;
    height: 60px;
    font-size: 20px;
}

.brand-name {
    font-size: 25px;
    letter-spacing: 0px;
    color: #eee;
}

.brand-caption {
    font-size: 15px;
    color: #B6D0D4;
}


.auth-card {
    width: 100%;
    max-width: 420px;
    height: 100%;
    padding: 40px;
}

/* Form layout */
.auth-card form {
    display: flex;
    flex-direction: column;
    gap: 20px;
}
.auth-card .form-group {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin: 0;
}
.auth-card label {
    color: #B6D0D4;
    font-size: 13px;
    font-weight: 600;
}
.auth-card input {
    width: 100%;
    min-height: 46px;
    padding: 12px 14px;
    color: #B6D0D4;
    background: #203F49;
    border: 1px solid #41616A;
    border-radius: 8px;
    outline: none;
    font-family: inherit;
    font-size: 14px;
    transition: border-color 160ms ease, box-shadow 160ms ease;
}
.auth-card input:hover {
    border-color: #9aabc2;
}
.auth-card input:focus {
    border-color: #2864c5;
    box-shadow: 0 0 0 3px rgba(40, 100, 197, 0.13);
}
/* Primary action */
.auth-card .primary-button {
    width: 100%;
    min-height: 47px;
    padding: 10px;
    color: #fff;
    background: var(--hisense);
    border: 1px solid var(--hisense-dark);
    border-radius: 8px;
    font-family: inherit;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    box-shadow: var(--shadow);
}
.auth-card .primary-button:hover:not(:disabled) {
    background: var(--hisense-dark);
    box-shadow: var(--shadow);
}
.auth-card .primary-button:active:not(:disabled) {
    transform: translateY(1px);
}
.auth-card .primary-button:disabled {
    opacity: 0.65;
    cursor: wait;
    box-shadow: none;
}
/* Feedback */
.auth-message {
    margin: 0;
    color: #f86f66;
    font-size: 13px;
    line-height: 1.5;
    white-space: pre-line;
    justify-content: center;
}
.auth-message:empty {
    display: none;
}
/* Secondary actions */
.auth-card .secondary-button {
    width: 100%;
    min-height: 44px;
    padding: 10px 16px;
    color: #344054;
    background: #ffffff;
    border: 1px solid #cfd8e5;
    border-radius: 8px;
    font-family: inherit;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: background 160ms ease, border-color 160ms ease;
}
.auth-card .secondary-button:hover:not(:disabled) {
    background: #f3f6fb;
    border-color: #9aabc2;
}
.auth-card .secondary-button:disabled {
    opacity: 0.65;
    cursor: wait;
}
/* Keyboard accessibility */
.auth-card button:focus-visible {
    outline: 3px solid rgba(40, 100, 197, 0.35);
    outline-offset: 3px;
}
/* Mobile */
@media (max-width: 480px) {
    .auth-container {
        padding: 20px 14px;
    }
    .auth-card {
        padding: 28px 22px;
        border-radius: 12px;
    }
    .auth-header {
        margin-bottom: 28px;
    }
    .auth-header h1 {
        font-size: 36px;
    }
}

