settings/settings.css:
.settings-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 20px;
    margin-bottom: 22px;
}

.settings-header h1 {
    margin: 0;
}

.settings-header p {
    margin: 6px 0 0;
    color: #6b7280;
}

.settings-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 16px;
}

.settings-card {
    display: grid;
    grid-template-columns: 48px minmax(0, 1fr) auto;
    align-items: center;
    gap: 16px;
    min-height: 132px;
    padding: 20px;
    color: inherit;
    text-align: left;
    text-decoration: none;
    background: #ffffff;
    border: 1px solid #dfe3e6;
    border-radius: 8px;
    cursor: pointer;
}

.settings-card:hover {
    border-color: #8bd8d8;
    background: #fbffff;
}

.settings-card:focus-visible {
    outline: 3px solid rgba(0, 154, 157, 0.22);
    outline-offset: 2px;
}

.settings-card-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    color: #007477;
    background: #e8f7f7;
    border: 1px solid #b7e5e5;
    border-radius: 8px;
    font-size: 13px;
    font-weight: 700;
}

.settings-card-content {
    display: flex;
    flex-direction: column;
    gap: 7px;
    min-width: 0;
}

.settings-card-content strong {
    font-size: 18px;
}

.settings-card-content span {
    color: #6b7280;
    font-size: 14px;
    line-height: 1.45;
}

.settings-card-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 76px;
    min-height: 36px;
    padding: 8px 12px;
    color: #ffffff;
    background: #009a9d;
    border-radius: 6px;
    font-size: 13px;
    font-weight: 700;
}

.settings-card-disabled {
    width: 100%;
    font: inherit;
    cursor: not-allowed;
    opacity: 0.68;
}

.settings-card-disabled:hover {
    border-color: #dfe3e6;
    background: #ffffff;
}

.settings-card-disabled .settings-card-action {
    color: #4b5563;
    background: #e5e7eb;
}

@media (max-width: 1100px) {
    .settings-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 620px) {
    .settings-card {
        grid-template-columns: 42px minmax(0, 1fr);
        gap: 14px;
        min-height: 128px;
        padding: 16px;
    }

    .settings-card-icon {
        width: 42px;
        height: 42px;
    }

    .settings-card-action {
        grid-column: 2;
        width: max-content;
    }
}

settings/roles/roles.css:
.roles-section {
    background: var(--surface-color, #ffffff);
    border: 1px solid var(--border-color, #e5e7eb);
    border-radius: 8px;
    overflow: hidden;
}
.page-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
}
.page-header h1 {
    margin: 0;
}
.page-header p {
    margin: 5px 0 0;
    color: #6b7280;
}
.section-header {
    padding: 18px 20px;
    border-bottom: 1px solid var(--border-color, #e5e7eb);
}
.section-header h2 {
    margin: 0;
}
.table-container {
    width: 100%;
    overflow-x: auto;
}
.roles-table {
    width: 100%;
    border-collapse: collapse;
}
.roles-table th,
.roles-table td {
    padding: 14px 20px;
    text-align: left;
    border-bottom: 1px solid var(--border-color, #e5e7eb);
}
.roles-table th {
    background: #f8fafc;
    font-weight: 600;
}
.roles-table tbody tr:last-child td {
    border-bottom: none;
}
.role-status {
    display: inline-flex;
    align-items: center;
    padding: 4px 10px;
    border-radius: 999px;
    font-size: 12px;
    font-weight: 600;
}
.role-status.active {
    background: #dcfce7;
    color: #166534;
}
.role-status.inactive {
    background: #fee2e2;
    color: #991b1b;
}
.role-actions {
    display: flex;
    gap: 8px;
}
.role-actions button {
    padding: 6px 10px;
    border: 1px solid #d1d5db;
    border-radius: 5px;
    background: #ffffff;
    cursor: pointer;
}
.role-actions button:hover {
    background: #f3f4f6;
}
.modal {
    position: fixed;
    inset: 0;
    z-index: 1000;
    display: flex;
    align-items: center;
    justify-content: center;
}
.modal.hidden {
    display: none;
}
.modal-overlay {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
}
.modal-content {
    position: relative;
    z-index: 1;
    width: min(900px, calc(100% - 40px));
    max-height: calc(100vh - 40px);
    background: #ffffff;
    border-radius: 10px;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.2);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}
.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    padding: 20px 24px;
    border-bottom: 1px solid #e5e7eb;
}
.modal-header h2 {
    margin: 0;
}
.modal-header p {
    margin: 5px 0 0;
    color: #6b7280;
}
.modal-close {
    border: none;
    background: transparent;
    font-size: 28px;
    line-height: 1;
    cursor: pointer;
    color: #6b7280;
}
.modal-close:hover {
    color: #111827;
}
#role-form {
    display: flex;
    flex-direction: column;
    min-height: 0;
}
.form-group {
    padding: 0 24px;
    margin-top: 18px;
}
.form-group label {
    display: block;
    margin-bottom: 7px;
    font-weight: 600;
}
.form-group input,
.form-group textarea {
    width: 100%;
    box-sizing: border-box;
    padding: 10px 12px;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font: inherit;
}
.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 2px rgba(37, 99, 235, 0.12);
}
.permissions-section {
    margin: 20px 24px 0;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    overflow: hidden;
}
.permissions-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px;
    background: #f8fafc;
    border-bottom: 1px solid #e5e7eb;
}
.permissions-header h3 {
    margin: 0;
}
.permissions-header p {
    margin: 4px 0 0;
    color: #6b7280;
    font-size: 14px;
}
#permissions-container {
    max-height: 350px;
    overflow-y: auto;
    padding: 16px;
}
.permission-module {
    border: 1px solid #e5e7eb;
    border-radius: 7px;
    margin-bottom: 12px;
    overflow: hidden;
}
.permission-module:last-child {
    margin-bottom: 0;
}
.permission-module-header {
    padding: 12px 14px;
    background: #f8fafc;
    font-weight: 600;
}
.permission-list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 8px 16px;
    padding: 14px;
}
.permission-item {
    display: flex;
    align-items: center;
    gap: 8px;
}
.permission-item input {
    width: 16px;
    height: 16px;
    cursor: pointer;
}
.permission-item label {
    cursor: pointer;
    font-size: 14px;
}
.form-message {
    min-height: 20px;
    margin: 12px 24px 0;
    font-size: 14px;
}
.form-message.error {
    color: #b91c1c;
}
.form-message.success {
    color: #15803d;
}
.modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 18px 24px;
    margin-top: 20px;
    border-top: 1px solid #e5e7eb;
}
.secondary-button {
    padding: 9px 14px;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    background: #ffffff;
    cursor: pointer;
}
.secondary-button:hover {
    background: #f3f4f6;
}
@media (max-width: 700px) {
    .page-header {
        align-items: flex-start;
        gap: 15px;
        flex-direction: column;
    }
    .permissions-header {
        align-items: flex-start;
        gap: 12px;
        flex-direction: column;
    }
    .permission-list {
        grid-template-columns: 1fr;
    }
    .roles-table th:nth-child(2),
    .roles-table td:nth-child(2) {
        display: none;
    }
