.user-actions {
    display: flex;
    gap: 8px;
}
.user-actions button {
    padding: 6px 10px;
    border: 1px solid #d1d5db;
    border-radius: 5px;
    background: #ffffff;
    cursor: pointer;
}

.modal {
    position: fixed;
    inset: 0;
    z-index: 1000;
    display: flex;
    align-items: center;
    justify-content: center;
}
.modal.hidden {
    display: none;
}
.modal-overlay {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
}
.modal-content {
    position: relative;
    z-index: 1;
    width: min(520px, calc(100% - 40px));
    background: #ffffff;
    border-radius: 10px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
    overflow: hidden;
}
.modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 18px 20px;
    border-bottom: 1px solid #e5e7eb;
}
.modal-header h2 {
    margin: 0;
    font-size: 20px;
}
.modal-header button {
    border: none;
    background: transparent;
    font-size: 24px;
    cursor: pointer;
}
#user-form {
    padding: 20px;
}
.form-group {
    margin-bottom: 16px;
}
.form-group label {
    display: block;
    margin-bottom: 6px;
    font-weight: 600;
}
.form-group input,
.form-group select {
    width: 100%;
    padding: 9px 10px;
    border: 1px solid #d1d5db;
    border-radius: 5px;
    font: inherit;
}
.form-message {
    min-height: 20px;
    margin-bottom: 10px;
    font-size: 14px;
}
.modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    padding-top: 10px;
}
.modal-footer button {
    padding: 8px 14px;
    border: 1px solid #d1d5db;
    border-radius: 5px;
    background: #ffffff;
    cursor: pointer;
}


