/* User actions window */
.user-actions-modal-content {
    position: relative;
    z-index: 1;
    width: min(760px, calc(100% - 32px));
    padding: 18px;
    background: #ffffff;
    border: 1px solid #303030;
    border-radius: 13px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
}
.user-actions-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 2px 0 18px;
    border-bottom: 1px solid #242424;
}
.user-summary {
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;
}
.user-avatar {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    background: rgb(255, 255, 255);
    border: 1px solid #383838;
    border-radius: 50%;
    font-size: 18px;
    font-weight: 600;
}
.user-summary h2 {
    margin: 0 0 5px;
    font-size: 16px;
    font-weight: 650;
}
.user-summary p {
    margin: 0;
    font-size: 13px;
    line-height: 1.5;
}
.close-actions-button {
    flex-shrink: 0;
    width: 34px;
    height: 34px;
    color: #dfdfdf;
    background: transparent;
    border: 1px solid transparent;
    border-radius: 7px;
    font-size: 24px;
    cursor: pointer;
}
.close-actions-button:hover {
    color: #111827;
}
.user-actions-grid {
    display: grid;
    grid-template-columns: repeat(1, minmax(0, 1fr));
    gap: 8px;
    padding-top: 20px;
}
.user-action-card {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 7px;
    min-height: 112px;
    padding: 14px;
    text-align: left;
    background: #f8fafc;
    border: 1px solid #e5e7eb;
    border-radius: 9px;
    cursor: pointer;
    transition: background 150ms ease, border-color 150ms ease;
}
.user-action-card:hover {
    background: #c3c5c7;
    border-color: var(--border-color)
}
.user-action-card:focus-visible,
.close-actions-button:focus-visible {
    outline: 2px solid #8ab4f8;
    outline-offset: 2px;
}
.user-action-icon {
    min-height: 20px;
    font-size: 19px;
    line-height: 1;
}
.user-action-card strong {
    font-size: 14px;
    font-weight: 650;
}
.user-action-card > span:last-child {
    font-size: 13px;
    line-height: 1.5;
}
.user-action-card[hidden] {
    display: none;
}
.user-actions-message {
    margin: 12px 0 0;
    color: #fca5a5;
    font-size: 13px;
}
.user-actions-message:empty {
    display: none;
}
@media (max-width: 520px) {
    .user-actions-modal-content {
        padding: 14px;
    }
    .user-actions-grid {
        gap: 7px;
        padding-top: 14px;
    }
    .user-action-card {
        min-height: 120px;
        padding: 11px;
    }
    .user-action-card strong {
        font-size: 13px;
    }
    .user-action-card > span:last-child {
        font-size: 12px;
    }
}


/* Users search */
.users-section-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
}
.users-search {
    display: flex;
    align-items: center;
    width: min(420px, 100%);
    min-width: 220px;
    min-height: 40px;
    background: var(--surface-color, #ffffff);
    border: 1px solid var(--border-color, #d1d5db);
    border-radius: 8px;
    overflow: hidden;
}
.users-search:focus-within {
    border-color: #2864c5;
    box-shadow: 0 0 0 3px rgba(40, 100, 197, 0.12);
}
.users-search input {
    width: 100%;
    min-width: 0;
    padding: 10px 12px;
    color: inherit;
    background: transparent;
    border: none;
    outline: none;
    font: inherit;
    font-size: 13px;
}
.users-search input:focus {
    outline: none;
    box-shadow: none;
}
.users-search button {
    flex-shrink: 0;
    width: 36px;
    height: 38px;
    color: #6b7280;
    background: transparent;
    border: none;
    font-size: 22px;
    cursor: pointer;
}
.users-search button:hover {
    color: #111827;
    background: #f3f4f6;
}
.users-search button[hidden] {
    display: none;
}
@media (max-width: 640px) {
    .users-section-header {
        align-items: stretch;
        flex-direction: column;
        gap: 12px;
    }
    .users-search {
        width: 100%;
        min-width: 0;
    }
}
